INSERT INTO public.forms (slug,titulo,introducao,ativo,prazo) VALUES ('oficina-de-regras','Oficina de Regras','Cada pessoa vai preencher a coluna "STORIAverso" de uma tabela comparativa de mecânicas de RPG. Não existe resposta certa. O objetivo é reunir ideias para decidirmos juntos.',true,'2026-11-15T23:59:00-03:00');
