INSERT INTO public.form_fields (form_id,ordem,bloco,chave,nome,status,o_que_e,exemplo,pergunta,definicao_atual,comparativo) SELECT id,1,'A · Motor de resolução','motor','Motor de resolução','propor','A regra principal de como se decide se uma ação dá certo: quais dados se rolam e como se calcula o resultado.','Rola-se 2d8 e soma-se o nível de Pilotagem. O resultado é comparado com a tempestade do dia.','Que dado ou combinação de dados deve decidir o resultado das ações no nosso jogo, e por quê?',NULL,'{"dnd": "1d20 + bônus", "ordem": "pool de d20, mantém o maior", "fabula": "dois dados, soma os resultados", "tdet": "1–3d6 + atributo", "swade": "dado de traço + Wild Die"}'::jsonb FROM public.forms WHERE slug='oficina-de-regras';
INSERT INTO public.form_fields (form_id,ordem,bloco,chave,nome,status,o_que_e,exemplo,pergunta,definicao_atual,comparativo) SELECT id,2,'A · Motor de resolução','dados','Dados principais','propor','Quais tipos de dado aparecem na mesa (d4, d6, d8, d10, d12, d20…).','Só d6 e d12: o d6 para tarefas comuns e o d12 para as heróicas.','Quais dados usaremos e que papel cada um tem?',NULL,'{"dnd": "d20", "ordem": "d20", "fabula": "d6, d8, d10, d12", "tdet": "d6", "swade": "d4, d6, d8, d10, d12"}'::jsonb FROM public.forms WHERE slug='oficina-de-regras';
INSERT INTO public.form_fields (form_id,ordem,bloco,chave,nome,status,o_que_e,exemplo,pergunta,definicao_atual,comparativo) SELECT id,3,'A · Motor de resolução','atributos','Atributos','propor','As características básicas que descrevem o personagem (força, mente, etc.). Poucos atributos deixam a ficha simples; muitos permitem mais especialização.','Três atributos: Vento (agilidade), Casco (resistência) e Bússola (percepção).','Quantos atributos o jogo deve ter e quais são, dado o nosso mundo?',NULL,'{"dnd": "6", "ordem": "5", "fabula": "4", "tdet": "3", "swade": "5"}'::jsonb FROM public.forms WHERE slug='oficina-de-regras';
INSERT INTO public.form_fields (form_id,ordem,bloco,chave,nome,status,o_que_e,exemplo,pergunta,definicao_atual,comparativo) SELECT id,4,'A · Motor de resolução','funcao_atributos','Função dos atributos','propor','Como o valor de um atributo entra na rolagem (somando número, mudando o tamanho do dado ou a quantidade de dados).','Cada ponto de Vento troca o dado de Pilotagem por um maior (d4, d6, d8…).','Como o atributo deve influenciar a rolagem?',NULL,'{"dnd": "modificadores numéricos", "ordem": "quantidade de d20", "fabula": "tamanho dos dados", "tdet": "valores numéricos diretos", "swade": "tamanho do dado"}'::jsonb FROM public.forms WHERE slug='oficina-de-regras';
INSERT INTO public.form_fields (form_id,ordem,bloco,chave,nome,status,o_que_e,exemplo,pergunta,definicao_atual,comparativo) SELECT id,5,'A · Motor de resolução','pericias','Perícias','propor','Habilidades específicas treináveis (hackear, investigar, esconder-se). Complementam os atributos.','Dez perícias fixas; cada uma soma +2 se o personagem for treinado.','O jogo terá perícias? Se sim, como funcionam e se ligam aos atributos?',NULL,'{"dnd": "proficiência + atributo", "ordem": "treinamento + atributo", "fabula": "sem lista tradicional", "tdet": "perícias, vantagens e desvantagens", "swade": "também por tamanho de dado"}'::jsonb FROM public.forms WHERE slug='oficina-de-regras';
INSERT INTO public.form_fields (form_id,ordem,bloco,chave,nome,status,o_que_e,exemplo,pergunta,definicao_atual,comparativo) SELECT id,6,'A · Motor de resolução','dificuldade','Dificuldade','propor','O número ou critério que a rolagem precisa alcançar. Pode ser fixo, definido pelo mestre ou em oposição a outra rolagem.','O mestre escolhe entre Calmaria (6), Vento Forte (10) e Tempestade (14).','Quem define a dificuldade, como é medida e que nome ela deve ter no nosso jogo?',NULL,'{"dnd": "CD", "ordem": "DT", "fabula": "nível de dificuldade", "tdet": "meta / oposição", "swade": "alvo 4 / oposição"}'::jsonb FROM public.forms WHERE slug='oficina-de-regras';
INSERT INTO public.form_fields (form_id,ordem,bloco,chave,nome,status,o_que_e,exemplo,pergunta,definicao_atual,comparativo) SELECT id,7,'B · Combate','defesa','Defesa','propor','O que torna um personagem mais difícil de atingir ou ferir (armadura, esquiva, bloqueio).','Defesa = 8 + armadura; gastando um turno, a pessoa pode ''manobrar'' para somar +3.','Como o personagem se protege? É um número fixo, uma escolha em cena ou os dois?',NULL,'{"dnd": "Classe de Armadura", "ordem": "defesa + reações", "fabula": "defesa e defesa mágica", "tdet": "valores simples / resistência", "swade": "Aparar e Robustez"}'::jsonb FROM public.forms WHERE slug='oficina-de-regras';
INSERT INTO public.form_fields (form_id,ordem,bloco,chave,nome,status,o_que_e,exemplo,pergunta,definicao_atual,comparativo) SELECT id,8,'B · Combate','combate','Combate','propor','A estrutura das cenas de luta: quem age quando, quão tático ou rápido é.','Rodadas curtas; cada pessoa faz uma ação principal e uma ação rápida.','Como deve ser o combate: tático, rápido, abstrato? Todos agem em turnos individuais ou em grupo?',NULL,'{"dnd": "turnos individuais, tático", "ordem": "turnos individuais, tático", "fabula": "turnos alternados, abstrato", "tdet": "rápido, direto, universal", "swade": "rápido, pulp, tático leve"}'::jsonb FROM public.forms WHERE slug='oficina-de-regras';
INSERT INTO public.form_fields (form_id,ordem,bloco,chave,nome,status,o_que_e,exemplo,pergunta,definicao_atual,comparativo) SELECT id,9,'B · Combate','iniciativa','Iniciativa','propor','Como se decide a ordem de ação no início do combate.','Cada pessoa rola Vento; quem tira mais age primeiro. Inimigos agem por último, em bloco.','Como a ordem dos turnos deve ser decidida e que nome ela pode ter no nosso mundo?',NULL,'{"dnd": "individual", "ordem": "individual", "fabula": "coletiva", "tdet": "simples", "swade": "cartas"}'::jsonb FROM public.forms WHERE slug='oficina-de-regras';
INSERT INTO public.form_fields (form_id,ordem,bloco,chave,nome,status,o_que_e,exemplo,pergunta,definicao_atual,comparativo) SELECT id,10,'B · Combate','dano','Dano','propor','Como se calcula o estrago de um ataque ou efeito e o que ele atinge.','Armas têm um dado de dano (d4 a d10) somado ao nível do atirador.','Como o dano deve ser calculado e o que ele atinge (corpo, mente, outro recurso)?',NULL,'{"dnd": "dados de dano", "ordem": "dados de dano", "fabula": "maior dado + bônus, em muitos ataques", "tdet": "enxuto", "swade": "rolagem separada, com explosão"}'::jsonb FROM public.forms WHERE slug='oficina-de-regras';
INSERT INTO public.form_fields (form_id,ordem,bloco,chave,nome,status,o_que_e,exemplo,pergunta,definicao_atual,comparativo) SELECT id,11,'C · Recursos e poderes','recursos','Recursos','propor','O que se gasta ou se perde durante o jogo (vida, energia, sanidade, tempo…).','Dois recursos: Casco (vida) e Combustível (energia para manobras).','Quais recursos o jogo terá, o que cada um mede e como se recuperam?',NULL,'{"dnd": "PV, magias, habilidades", "ordem": "PV, PE, Sanidade", "fabula": "PV, PM, Inventário, Pontos Fabula", "tdet": "PV, PM, Pontos de Ação", "swade": "Bennies, Ferimentos, Fadiga"}'::jsonb FROM public.forms WHERE slug='oficina-de-regras';
INSERT INTO public.form_fields (form_id,ordem,bloco,chave,nome,status,o_que_e,exemplo,pergunta,definicao_atual,comparativo) SELECT id,12,'C · Recursos e poderes','poderes','Poderes','definido','As habilidades especiais e sobrenaturais dos personagens.','Cada poder tem um nome, um custo e um efeito, como ''Rajada de Vento''.','Concorda com a definição? Que ajuste faria?','Manifestação, Função, Glitch e comando por assistente virtual.','{"dnd": "magias e habilidades", "ordem": "rituais e habilidades", "fabula": "habilidades de classe", "tdet": "vantagens, técnicas, poderes especiais", "swade": "poderes flexíveis"}'::jsonb FROM public.forms WHERE slug='oficina-de-regras';
INSERT INTO public.form_fields (form_id,ordem,bloco,chave,nome,status,o_que_e,exemplo,pergunta,definicao_atual,comparativo) SELECT id,13,'C · Recursos e poderes','classes','Classes','definido','Arquétipos de personagem que agrupam poderes e perícias.','Três classes: Piloto, Mecânica e Navegadora, cada uma com 5 habilidades.','Concorda? Há algo a ajustar (nomes, combinações, multiclasse)?','Mentalista, Mecânico, Naturalista, Físico e Suporte.','{"dnd": "classes e subclasses", "ordem": "classes e trilhas", "fabula": "multiclasse modular", "tdet": "arquétipos / conceito", "swade": "sem classes rígidas"}'::jsonb FROM public.forms WHERE slug='oficina-de-regras';
INSERT INTO public.form_fields (form_id,ordem,bloco,chave,nome,status,o_que_e,exemplo,pergunta,definicao_atual,comparativo) SELECT id,14,'C · Recursos e poderes','progressao','Progressão','propor','Como o personagem evolui ao longo da campanha.','A cada missão cumprida, o grupo escolhe uma melhoria para o dirigível.','Como o personagem deve evoluir: por níveis, por marcos da história, por upgrades?',NULL,'{"dnd": "níveis 1–20", "ordem": "NEX", "fabula": "níveis e multiclasse", "tdet": "XP e evolução", "swade": "avanços"}'::jsonb FROM public.forms WHERE slug='oficina-de-regras';
INSERT INTO public.form_fields (form_id,ordem,bloco,chave,nome,status,o_que_e,exemplo,pergunta,definicao_atual,comparativo) SELECT id,15,'D · Risco e tom','falhas_criticas','Falhas críticas','definido','O que acontece quando uma rolagem falha de forma extrema.','Tirar 1 nos dois dados faz o dirigível perder a vela.','Concorda? Que consequências um glitch deveria ter?','Glitch exige confirmação adicional após falha crítica.','{"dnd": "falha automática no ataque", "ordem": "falhas com efeitos conforme regras", "fabula": "dois dados mostrando 1", "tdet": "menos dramáticas", "swade": "1 no dado de traço e no Wild Die"}'::jsonb FROM public.forms WHERE slug='oficina-de-regras';
INSERT INTO public.form_fields (form_id,ordem,bloco,chave,nome,status,o_que_e,exemplo,pergunta,definicao_atual,comparativo) SELECT id,16,'D · Risco e tom','risco_adicional','Risco adicional','propor','Os perigos próprios do mundo além do dano comum (sanidade, exposição, perda de memória…).','Ao voar sem rota, o grupo acumula ''Desorientação'', que atrapalha as rolagens.','Que riscos extras devem existir no nosso mundo e quais são as consequências?',NULL,'{"dnd": "morte, condições, exaustão", "ordem": "sanidade, paranormal", "fabula": "condições, rendição e sacrifício", "tdet": "baixa letalidade / ação", "swade": "abalado, ferimentos, fadiga"}'::jsonb FROM public.forms WHERE slug='oficina-de-regras';
INSERT INTO public.form_fields (form_id,ordem,bloco,chave,nome,status,o_que_e,exemplo,pergunta,definicao_atual,comparativo) SELECT id,17,'D · Risco e tom','enfase','Ênfase de design','definido','O tipo de experiência que o jogo quer entregar (ação, investigação, estratégia, narrativa).','Aventura de exploração com tomada de decisão em equipe e ritmo rápido.','Concorda? O que está faltando ou sobrando?','Thriller de investigação, infiltração e conflito velado.','{"dnd": "fantasia heroica e tática", "ordem": "investigação e combate paranormal", "fabula": "JRPG e narrativa compartilhada", "tdet": "ação rápida, anime, flexível", "swade": "ação rápida, pulp, flexível e cinematográfica"}'::jsonb FROM public.forms WHERE slug='oficina-de-regras';